import { mdsvex } from 'mdsvex';
import adapter from '@sveltejs/adapter-auto';

/** @type {import('@sveltejs/kit').Config} */
const config = {
	kit: { // adapter-auto only supports some environments, see https://svelte.dev/docs/kit/adapter-auto for a list.
	// If your environment is not supported, or you settled on a specific environment, switch out the adapter.
	// See https://svelte.dev/docs/kit/adapters for more information about adapters.
	adapter: adapter() },
	preprocess: [mdsvex()],
	extensions: ['.svelte', '.svx']
};

export default config;

/**
 * Blog utilities for loading and managing markdown posts
 */

/**
 * Get all blog posts with their metadata
 * @returns {Promise<Array>} Array of post objects with metadata and slug
 */
export async function getPosts() {
  const postFiles = import.meta.glob("/src/posts/*.md");
  const posts = [];

  for (const path in postFiles) {
    const post = await postFiles[path]();
    const slug = path.split("/").pop().replace(".md", "");

    posts.push({
      slug,
      title: post.metadata.title,
      date: post.metadata.date,
      excerpt: post.metadata.excerpt,
    });
  }

  // Sort posts by date (newest first)
  posts.sort((a, b) => new Date(b.date) - new Date(a.date));

  return posts;
}

/**
 * Get a single blog post by slug
 * @param {string} slug - The post slug
 * @returns {Promise<Object>} Post object with metadata and content
 */
export async function getPost(slug) {
  const post = await import(`../posts/${slug}.md`);

  return {
    slug,
    ...post.metadata,
    content: post.default,
  };
}

